#include "codane/agent.hpp"
#include <thread>
namespace codane {
AgentResult FakeProvider::run(const AgentRequest&r,std::stop_token s){int a=++active;int old=peak.load();while(a>old&&!peak.compare_exchange_weak(old,a)){}AgentResult x;if(s.stop_requested())x.status=NodeState::Cancelled;else if(fn)x=fn(r);else{x.status=NodeState::Succeeded;x.stdout_text="fake:"+r.id;}--active;return x;}
static void backoff(const RetryPolicy&p,int attempt){auto d=p.backoff;for(int i=1;i<attempt;i++)d=std::chrono::milliseconds(std::min<int64_t>(d.count()*p.multiplier,60000));std::this_thread::sleep_for(std::min(d,std::chrono::milliseconds(20)));}
AgentResult run_with_retry(AgentProvider&p,const AgentRequest&base,const RetryPolicy&policy,Cancellation&c,const std::function<void(int)>&cb){AgentResult last;int max=std::max(1,policy.max_attempts);for(int attempt=base.attempt;attempt<=max&&!c.cancelled();++attempt){if(cb)cb(attempt);auto r=base;r.attempt=attempt;last=p.run(r,c.source.get_token());last.attempts=attempt;if(last.status==NodeState::Succeeded||last.status==NodeState::Cancelled)return last;if(attempt<max)backoff(policy,attempt);}if(c.cancelled())last.status=NodeState::Cancelled;return last;}
AgentResult run_verified(AgentProvider&p,const AgentRequest&base,const RetryPolicy&policy,Cancellation&c,const std::function<std::unique_ptr<Verifier>()>&make){AgentResult last;int max=std::max(1,policy.max_attempts);for(int attempt=base.attempt;attempt<=max&&!c.cancelled();++attempt){auto q=base;q.attempt=attempt;last=p.run(q,c.source.get_token());last.attempts=attempt;if(last.status==NodeState::Succeeded){std::string error;auto v=make();if(v&&v->verify(&error)){last.verifier_ran=true;last.verifier_error=error;last.status=NodeState::Succeeded;last.stderr_text=error;return last;}last.verifier_ran=true;last.verifier_error=error;last.status=NodeState::Failed;last.stderr_text=error;}if(last.status==NodeState::Cancelled)return last;if(attempt<max)backoff(policy,attempt);}if(c.cancelled())last.status=NodeState::Cancelled;return last;}
}
